// This is file of your component
// You can use any dependencies from npm; we import them automatically in package.json

"use client";

import * as React from "react";
import { motion, useReducedMotion, type TargetAndTransition } from "framer-motion";
import { cn } from "@/lib/utils";



/* ------------------------------------------------------------------ */
/* Types                                                               */
/* ------------------------------------------------------------------ */

export type VisualizerState = "idle" | "listening" | "thinking" | "speaking";
export type VisualizerSize = "sm" | "md" | "lg";

export interface AIVoiceVisualizerProps {
  state?: VisualizerState;
  size?: VisualizerSize;
  /** Real microphone level from 0 to 1. Omit it to simulate input while listening. */
  level?: number;
  /** Number of bars (5 to 15, odd numbers look best). */
  bars?: number;
  /** Accessible label. Defaults to a description of the current state. */
  label?: string;
  className?: string;
}

// Bar thickness in px for each size. Everything else is derived from it
const UNIT: Record<VisualizerSize, number> = { sm: 4, md: 6, lg: 8 };

const STATE_LABEL: Record<VisualizerState, string> = {
  idle: "Voice assistant is idle",
  listening: "Voice assistant is listening",
  thinking: "Voice assistant is thinking",
  speaking: "Voice assistant is speaking",
};


// Looping transition for keyframe pulses
const loop = (duration: number, delay = 0) => ({ duration, delay, repeat: Infinity, ease: "easeInOut" as const });



/* ------------------------------------------------------------------ */
/* Simulated microphone input                                          */
/* ------------------------------------------------------------------ */

// Produces a smooth, speech-like level (0 to 1) for each bar, centre bars loudest
function useSimulatedLevels(active: boolean, count: number, external?: number) {
  const [levels, setLevels] = React.useState<number[]>(() => Array(count).fill(0.2));

  React.useEffect(() => {
    if (!active) {
      setLevels(Array(count).fill(0.2));
      return;
    }
    let amp = 0.5; // slow-moving "loudness" so the waves swell and fall like speech
    const mid = (count - 1) / 2;
    const id = window.setInterval(() => {
      amp = Math.min(1, Math.max(0.15, amp + (Math.random() - 0.5) * 0.5));
      setLevels((prev) =>
        Array.from({ length: count }, (_, i) => {
          const env = 1 - (Math.abs(i - mid) / (mid + 1)) * 0.65;
          const loudness = external ?? amp;
          const target = Math.min(1, env * (0.2 + loudness * 0.8 * (0.5 + Math.random() * 0.5)));
          return (prev[i] ?? 0.2) * 0.35 + target * 0.65; // smoothing
        })
      );
    }, 90);
    return () => window.clearInterval(id);
  }, [active, count, external]);

  return levels;
}



/* ------------------------------------------------------------------ */
/* Component                                                           */
/* ------------------------------------------------------------------ */

export function AIVoiceVisualizer({ state = "idle", size = "md", level, bars = 9, label, className }: AIVoiceVisualizerProps) {
  const reduced = !!useReducedMotion();
  const count = Math.max(5, Math.min(15, Math.round(bars)));
  const mid = (count - 1) / 2;
  const centre = Math.floor(mid);

  // All measurements come from one unit, and the box is fixed, so switching states never shifts the layout
  const u = UNIT[size];
  const gap = u * 2.2;
  const maxH = u * 12;
  const radius = u * 3.4;
  const dot = u * 0.9;
  const boxW = count * gap + u * 2;
  const boxH = maxH + u * 2;

  const levels = useSimulatedLevels(state === "listening" && !reduced, count, level);

  // Outer element: where the bar is and how big (spring-animated, so every state change morphs smoothly)
  const outerTarget = (i: number, env: number, angle: number): TargetAndTransition => {
    const x = (i - mid) * gap;
    switch (state) {
      case "idle":
        return i === centre
          ? { width: u * 1.6, height: u * 1.6, x: 0, y: 0, opacity: 1 }
          : { width: u * 0.6, height: u * 0.6, x: 0, y: 0, opacity: 0 };
      case "listening":
        return { width: u, height: Math.max(u, (reduced ? env * 0.5 : levels[i] ?? 0.2) * maxH), x, y: 0, opacity: 1 };
      case "thinking":
        return { width: dot, height: dot, x: Math.cos(angle) * radius, y: Math.sin(angle) * radius, opacity: 1 };
      case "speaking":
        return { width: u, height: Math.max(u * 1.2, maxH * (0.35 + 0.65 * env) * (reduced ? 0.8 : 1)), x, y: 0, opacity: 1 };
    }
  };

  // Inner element: the looping pulse. Every loop starts and ends at rest, so entering a state never jumps
  const innerTarget = (i: number): TargetAndTransition => {
    const rest: TargetAndTransition = { scale: 1, scaleY: 1, opacity: 1, transition: { duration: 0.3 } };
    if (reduced) return rest;
    switch (state) {
      case "idle":
        return i === centre
          ? { scale: [1, 1.25, 1], opacity: [1, 0.75, 1], scaleY: 1, transition: { scale: loop(3.2), opacity: loop(3.2), default: { duration: 0.3 } } }
          : rest;
      case "thinking":
        return { scale: [1, 0.55, 1], opacity: [1, 0.4, 1], scaleY: 1, transition: { scale: loop(1.2, i * 0.12), opacity: loop(1.2, i * 0.12), default: { duration: 0.3 } } };
      case "speaking":
        return {
          scaleY: [1, 0.4 + 0.08 * (i % 3), 1, 0.65, 1],
          scale: 1,
          opacity: 1,
          transition: { scaleY: loop(0.9 + (i % 4) * 0.13, i * 0.05), default: { duration: 0.3 } },
        };
      default:
        return rest;
    }
  };

  // Listening gets a bouncier spring so the bars feel responsive
  const outerTransition = reduced
    ? { duration: 0.2 }
    : { type: "spring" as const, stiffness: state === "listening" ? 420 : 200, damping: state === "listening" ? 15 : 24, mass: 0.6 };

  const thinking = state === "thinking" && !reduced;

  return (
    <div
      role="img"
      aria-label={label ?? STATE_LABEL[state]}
      className={cn("relative grid max-w-full shrink-0 place-items-center", className)}
      style={{ width: boxW, height: boxH }}
    >
      {/* Soft glow that follows the theme's primary colour */}
      <motion.div
        aria-hidden="true"
        initial={false}
        className="absolute inset-0 m-auto rounded-full bg-primary/30 blur-2xl"
        style={{ width: boxH * 1.1, height: boxH * 1.1 }}
        animate={
          reduced
            ? { opacity: 0.35, scale: 1 }
            : state === "idle"
              ? { opacity: 0.25, scale: [1, 1.25, 1], transition: { scale: loop(3.2), default: { duration: 0.4 } } }
              : state === "speaking"
                ? { opacity: 0.55, scale: [1, 1.15, 1], transition: { scale: loop(1.4), default: { duration: 0.4 } } }
                : { opacity: state === "thinking" ? 0.4 : 0.5, scale: 1, transition: { duration: 0.4 } }
        }
      />

      {/* The whole group rotates while thinking, which turns the dots into an orbit */}
      <motion.div
        aria-hidden="true"
        initial={false}
        className="absolute inset-0 grid place-items-center"
        animate={{ rotate: thinking ? 360 : 0 }}
        transition={thinking ? { duration: 2.6, repeat: Infinity, ease: "linear" } : { duration: 0.5, ease: "easeOut" }}
      >
        {Array.from({ length: count }, (_, i) => {
          const env = 1 - (Math.abs(i - mid) / (mid + 1)) * 0.65;
          const angle = (i / count) * Math.PI * 2 - Math.PI / 2;
          return (
            <motion.span
              key={i}
              initial={false}
              animate={outerTarget(i, env, angle)}
              transition={outerTransition}
              className="col-start-1 row-start-1 flex items-center justify-center"
            >
              <motion.span initial={false} animate={innerTarget(i)} className="block size-full rounded-full bg-primary" />
            </motion.span>
          );
        })}
      </motion.div>
    </div>
  );
}

